files = []
def walk(path):
    for name in repo.list(path):
        full = path + "/" + name if path != "." else name
        if name.endswith("/"):
            walk(full.rstrip("/"))
        else:
            files.append(full)

walk("data")
txt = sorted([f for f in files if f.endswith(".txt")])
counts = []
total = 0
for f in txt:
    c = repo.read(f)
    n = len(c.splitlines())
    counts.append((f, n))
    total += n
return {"files": counts, "total": total}
